WITH matched_keys AS (SELECT region, id FROM stores EXCEPT ALL SELECT region, id FROM stores WHERE city IN ('Berlin', 'Singapore')), reconciled AS (SELECT s.* FROM stores s JOIN matched_keys k ON s.region = k.region AND s.id = k.id) SELECT id, store_name, city, region, opened_date, CASE WHEN region RLIKE '^(Central|East)$' THEN 'GROUP_A' WHEN region RLIKE '^(North|South)$' THEN 'CORE' ELSE 'OTHER_ZONE' END AS region_zone FROM reconciled ORDER BY id DESC
